function phraseLoc(section, idx, p){
  if (APP_LANG !== 'tr' && PHRASES_I18N[APP_LANG] && PHRASES_I18N[APP_LANG][section] && PHRASES_I18N[APP_LANG][section][idx]) {
    const L = PHRASES_I18N[APP_LANG][section][idx];
    return { tr: (L.tr != null ? L.tr : p.tr), ph: (L.ph != null ? L.ph : p.ph), alt: (L.alt != null ? L.alt : p.alt) };
  }
  return { tr: p.tr, ph: p.ph, alt: p.alt };
}


