function quizLoc(item){
  const aid = item && item.audioId;
  const tr = (APP_LANG!=='tr' && aid && QUIZ_I18N[APP_LANG] && QUIZ_I18N[APP_LANG][aid]!=null) ? QUIZ_I18N[APP_LANG][aid] : item.tr;
  return { tr: tr, q: promptLoc(item.q || '') };
}

